use futures::{SinkExt, StreamExt};
use tokio_util::codec::{Framed, LengthDelimitedCodec};

#[derive(Serialize, Deserialize)] enum Msg { Reserve { id: u64, qty: u32 } }

let mut peer = Framed::new(TcpStream::connect("peer2:9002").await?,
                           LengthDelimitedCodec::new());
peer.send(Bytes::from(serde_json::to_vec(&Msg::Reserve { id: 7, qty: 3 })?)).await?;
while let Some(frame) = peer.next().await {                    // receiver loop
    dispatch(serde_json::from_slice::<Msg>(&frame?)?);         // peer method
}
